CREATE TABLE IF NOT EXISTS users (
 id text PRIMARY KEY, email text UNIQUE NOT NULL, password_hash text NOT NULL, name text NOT NULL,
 role text NOT NULL DEFAULT 'user' CHECK(role IN ('user','seller','admin')), verified boolean NOT NULL DEFAULT false,
 suspended boolean NOT NULL DEFAULT false, bio text NOT NULL DEFAULT '', avatar text, created_at timestamptz NOT NULL DEFAULT now()
);
CREATE TABLE IF NOT EXISTS sessions (token_hash text PRIMARY KEY, user_id text NOT NULL REFERENCES users(id), expires_at timestamptz NOT NULL);
CREATE TABLE IF NOT EXISTS auth_tokens (token_hash text PRIMARY KEY,user_id text REFERENCES users(id),kind text NOT NULL,expires_at timestamptz NOT NULL);
CREATE TABLE IF NOT EXISTS addresses (id text PRIMARY KEY,user_id text REFERENCES users(id),label text NOT NULL,data jsonb NOT NULL);
CREATE TABLE IF NOT EXISTS seller_private (user_id text PRIMARY KEY REFERENCES users(id),legal_name text NOT NULL,document text NOT NULL,provider_status text NOT NULL DEFAULT 'sandbox',provider_id text);
CREATE TABLE IF NOT EXISTS cards (id text PRIMARY KEY,franchise text NOT NULL,name text NOT NULL,product_type text NOT NULL);
CREATE TABLE IF NOT EXISTS editions (id text PRIMARY KEY,card_id text REFERENCES cards(id),collection text NOT NULL,code text NOT NULL,rarity text NOT NULL,language text NOT NULL,finish text NOT NULL,art text NOT NULL);
CREATE TABLE IF NOT EXISTS listings (id text PRIMARY KEY,seller_id text NOT NULL REFERENCES users(id),edition_id text REFERENCES editions(id),title text NOT NULL,description text NOT NULL,condition text NOT NULL,grading text,price integer NOT NULL CHECK(price>0),stock integer NOT NULL CHECK(stock>=0),status text NOT NULL DEFAULT 'active' CHECK(status IN ('active','paused','closed','pending')),photos jsonb NOT NULL DEFAULT '[]',demo boolean NOT NULL DEFAULT true,created_at timestamptz NOT NULL DEFAULT now());
CREATE INDEX IF NOT EXISTS listings_edition ON listings(edition_id);
CREATE TABLE IF NOT EXISTS favorites (user_id text REFERENCES users(id),listing_id text REFERENCES listings(id),PRIMARY KEY(user_id,listing_id));
CREATE TABLE IF NOT EXISTS affiliates (id text PRIMARY KEY,title text NOT NULL,description text NOT NULL,franchise text NOT NULL,category text NOT NULL,platform text NOT NULL,external_seller text NOT NULL,url text NOT NULL,image text NOT NULL,reference_price integer,active boolean NOT NULL DEFAULT true,updated_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS affiliate_clicks (id text PRIMARY KEY,affiliate_id text REFERENCES affiliates(id),created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS campaigns (id text PRIMARY KEY,seller_id text REFERENCES users(id),title text NOT NULL,description text NOT NULL,price integer NOT NULL CHECK(price>0),rules jsonb NOT NULL,version integer NOT NULL DEFAULT 1,status text NOT NULL DEFAULT 'draft' CHECK(status IN ('draft','active','paused')),demo boolean NOT NULL DEFAULT true,created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS physical_cards (id text PRIMARY KEY,campaign_id text REFERENCES campaigns(id),edition_id text REFERENCES editions(id),group_name text NOT NULL,condition text NOT NULL,photo text NOT NULL,declared_value integer NOT NULL CHECK(declared_value>=0),reference_value integer,reference_source text,reference_date date,state text NOT NULL DEFAULT 'available' CHECK(state IN ('available','reserved','sold')),reserved_order text);
CREATE TABLE IF NOT EXISTS orders (id text PRIMARY KEY,buyer_id text REFERENCES users(id),status text NOT NULL DEFAULT 'pending' CHECK(status IN ('pending','paid','expired','cancelled','refunded','partially_refunded','late_payment')),subtotal integer NOT NULL,shipping integer NOT NULL,total integer NOT NULL,commission integer NOT NULL,refunded integer NOT NULL DEFAULT 0,expires_at timestamptz NOT NULL,idempotency_key text NOT NULL,address_snapshot jsonb NOT NULL,created_at timestamptz NOT NULL DEFAULT now(), UNIQUE(buyer_id,idempotency_key));
CREATE TABLE IF NOT EXISTS suborders (id text PRIMARY KEY,order_id text REFERENCES orders(id),seller_id text REFERENCES users(id),subtotal integer NOT NULL,shipping integer NOT NULL,commission integer NOT NULL,status text NOT NULL DEFAULT 'pending',tracking text,UNIQUE(order_id,seller_id));
CREATE TABLE IF NOT EXISTS order_items (id text PRIMARY KEY,order_id text REFERENCES orders(id),suborder_id text REFERENCES suborders(id),listing_id text REFERENCES listings(id),campaign_id text REFERENCES campaigns(id),quantity integer NOT NULL,unit_price integer NOT NULL,subtotal integer NOT NULL,commission integer NOT NULL,refunded integer NOT NULL DEFAULT 0,commission_reversed integer NOT NULL DEFAULT 0,snapshot jsonb NOT NULL);
CREATE TABLE IF NOT EXISTS booster_results (id text PRIMARY KEY,order_id text REFERENCES orders(id),item_id text REFERENCES order_items(id),physical_id text REFERENCES physical_cards(id),snapshot jsonb NOT NULL,revealed boolean NOT NULL DEFAULT false,UNIQUE(item_id,physical_id));
CREATE TABLE IF NOT EXISTS payments (id text PRIMARY KEY,order_id text UNIQUE REFERENCES orders(id),provider text NOT NULL,method text NOT NULL,status text NOT NULL,amount integer NOT NULL,fee integer NOT NULL DEFAULT 0);
CREATE TABLE IF NOT EXISTS webhook_events (provider text NOT NULL,event_id text NOT NULL,payload_hash text NOT NULL,created_at timestamptz NOT NULL DEFAULT now(),PRIMARY KEY(provider,event_id));
CREATE TABLE IF NOT EXISTS refunds (id text PRIMARY KEY,order_id text REFERENCES orders(id),item_id text REFERENCES order_items(id),amount integer NOT NULL,commission_reversed integer NOT NULL,idempotency_key text UNIQUE NOT NULL,created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS messages (id text PRIMARY KEY,order_id text REFERENCES orders(id),author_id text REFERENCES users(id),body text NOT NULL,created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS reviews (id text PRIMARY KEY,order_id text REFERENCES orders(id),buyer_id text REFERENCES users(id),seller_id text REFERENCES users(id),rating integer NOT NULL CHECK(rating BETWEEN 1 AND 5),body text NOT NULL,created_at timestamptz NOT NULL DEFAULT now(),UNIQUE(order_id,seller_id));
CREATE TABLE IF NOT EXISTS disputes (id text PRIMARY KEY,order_id text REFERENCES orders(id),listing_id text REFERENCES listings(id),user_id text REFERENCES users(id),reason text NOT NULL,evidence jsonb NOT NULL,status text NOT NULL DEFAULT 'open',created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS notifications (id text PRIMARY KEY,user_id text REFERENCES users(id),body text NOT NULL,read boolean NOT NULL DEFAULT false,created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS audit (id text PRIMARY KEY,actor_id text,action text NOT NULL,entity_id text NOT NULL,data jsonb NOT NULL,created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS rate_limits (key text PRIMARY KEY,count integer NOT NULL,expires_at timestamptz NOT NULL);
